            stack = [(r, c)]
            seen.add((r, c))
            pts = []
            while stack:
                y, x = stack.pop()
                pts.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            minr = min(y for y, x in pts)
            maxr = max(y for y, x in pts)
            minc = min(x for y, x in pts)
            maxc = max(x for y, x in pts)
            objs.append({'color': color, 'pts': pts, 'r0': minr, 'r1': maxr,
