    return objs


def has_hole(obj):
    pts = {(r, c) for r, c in obj['pts']}
    r0, r1, c0, c1 = obj['r0'], obj['r1'], obj['c0'], obj['c1']
    # Flood background cells from the bounding-box border; unreachable zeros are holes.
    todo = []
    reached = set()
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if (r, c) not in pts and (r, c) not in reached:
                    reached.add((r, c))
                    todo.append((r, c))
    while todo:
        r, c = todo.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            q = (r + dr, c + dc)
            if r0 <= q[0] <= r1 and c0 <= q[1] <= c1 and q not in pts and q not in reached:
                reached.add(q)
                todo.append(q)
    return any((r, c) not in pts and (r, c) not in reached
               for r in range(r0, r1 + 1) for c in range(c0, c1 + 1))


def transform(grid):
    h, w = len(grid), len(grid[0])
    objs = components(grid)
    top = [o for o in objs if has_hole(o)]
    bottom = [o for o in objs if not has_hole(o)]
    placed = []

    # Hollow objects rise to the top, retaining their vertical order when their
    # horizontal spans overlap; non-hollow objects similarly settle at the bottom.
    top.sort(key=lambda o: (o['r0'], o['c0']))
    for o in top:
        height = o['r1'] - o['r0'] + 1
        start = 0
        for p in placed:
            if p['side'] == 'top' and not (o['c1'] < p['c0'] or p['c1'] < o['c0']):
                start = max(start, p['r1'] + 1)
        placed.append(dict(o, side='top', nr0=start, nr1=start + height - 1))

    bottom.sort(key=lambda o: (-o['r1'], o['c0']))
    for o in bottom:
        height = o['r1'] - o['r0'] + 1
        end = h - 1
        for p in placed:
            if p['side'] == 'bottom' and not (o['c1'] < p['c0'] or p['c1'] < o['c0']):
                end = min(end, p['nr0'] - 1)
        placed.append(dict(o, side='bottom', nr0=end - height + 1, nr1=end))

    out = [[0] * w for _ in range(h)]
    for o in placed:
        shift = o['nr0'] - o['r0']
        for r, c in o['pts']:
            out[r + shift][c] = o['color']
    return out
